def paginate(items,page,size):
    pages = 0
    items_list = [[i] for i in items]
    total = len(items)
    if not items:
        return {items: items_list, total: total, pages: 0}
    for p in range(page, size + 1):
        if p > page:
            pages = p - page
            break
        items_list.append(items[(page - 1) * size + p])
    return {items: items_list, total: total, pages: pages}

